"""A sound dialog opened mid-deal cannot swallow the repeat prompt."""
import os
from playwright.sync_api import sync_playwright,expect
base=os.environ.get('UNITY_URL','http://127.0.0.1:3483')
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':800,'height':1300});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(base+'/baccarat/index.html');page.locator('[data-classic=start]').click();page.locator('[data-classic="bet:player"]').click();page.locator('[data-classic="chip:100"]').click();page.locator('[data-classic=deal]').click();page.locator('[data-classic=sound]').click();expect(page.get_by_role('dialog',name='サウンド設定')).to_be_visible();page.wait_for_function('()=>CLASSIC.controller.session.state.phase==="result"');page.wait_for_timeout(1600);page.get_by_role('button',name='OK',exact=True).click();expect(page.get_by_role('dialog',name='リベットを行いますか？')).to_be_visible(timeout=2000);assert page.evaluate('()=>CLASSIC.controller.session.state.stats.rounds')==1;page.get_by_role('button',name='いいえ',exact=True).click();page.locator('[data-classic="bet:player"]').click();page.locator('[data-classic="chip:100"]').click();page.locator('[data-classic=deal]').click();page.locator('[data-classic=home]').click();page.get_by_role('button',name='Yes',exact=True).click();expect(page.locator('[data-classic=start]')).to_be_visible();page.wait_for_timeout(1500);assert page.evaluate('()=>CLASSIC.controller.session.state.stats.rounds')==2;assert not errors,errors;b.close()
print('mid-deal sound close returns to repeat, home settles once and cancels old callbacks')
